	switch s {
	case "pending":
		return StatusPending, nil
	case "active":
		return StatusActive, nil
	case "revoked":
		return StatusRevoked, nil
	}

	var zero Status
	return zero, errors.New(strconv.Quote(s) + " is not a member of Status")
